import {Renderer} from './renderer.js';
import * as E from './engine.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,extras='')=>`<button class="secondary" data-action="${action}" ${extras}>${label}</button>`;
export function worldPanel(s){
  const f=s.frontier,rates=E.colonyRates(s);
  return `<section class="world-overview"><div class="eyebrow">EXPANSIÓN PROCEDURAL · SEMILLA ${f.seed}</div><h2>Un continente por descubrir.</h2><p>24 regiones de 40 × 40 casillas · 6 biomas · 3 civilizaciones. Cada ejército revela su mapa al explorar. Conquista una base para abrir las regiones vecinas.</p><div class="world-stats"><span>BASE INICIAL<strong>48 × 48</strong></span><span>TERRITORIOS<strong>${f.regions.filter(r=>r.status==='owned').length} / 24</strong></span><span>COLONIAS<strong>${f.colonies.length}</strong></span><span>EXPORTACIONES<strong>+${Object.values(rates).reduce((a,b)=>a+b,0).toFixed(1)}/s</strong></span></div><div class="region-grid">${f.regions.map(r=>{const known=r.status!=='hidden',b=E.BIOMES[r.biome];return `<button class="region-tile region-${r.status}" data-action="region-detail" data-id="${r.id}" style="--biome:${known?b.color:'#263e42'}" ${known?'':'disabled'}><span>${known?r.biome===3?'⚓':'⚑':'?'}</span><strong>${known?esc(r.name):'Sin explorar'}</strong><small>${known?b.name+' · '+({owned:'TU TERRITORIO',open:'EXPEDICIÓN',allied:'ALIADO'}[r.status]):'Conquista una región vecina'}</small></button>`;}).join('')}</div><p>La región elegida aparece abajo. Las rutas gastan aleación durante la expedición; sin abastecimiento, el ejército avanza más despacio.</p><div id="region-detail">${regionDetail(s,f.regions.find(r=>r.status==='open')?.id??0)}</div><h3>Minerales y comercio regional</h3><div class="mineral-grid">${E.BIOMES.map((b,i)=>'<div><b>'+b.mineral+'</b><strong>'+Math.floor(f.minerals[i])+'</strong>'+button('trade-mineral','Vender 10 · ◈ '+[120,140,180,200,220,260][i],'data-id="'+i+'" '+(f.minerals[i]<10?'disabled':''))+'</div>').join('')}</div><h3>Diplomacia con civilizaciones de IA</h3><div class="faction-grid">${E.FACTIONS.map((v,i)=>`<article class="faction-card"><h3>${v.name}</h3><p>${v.description}</p><p>${v.bonus}</p><progress max="100" value="${f.relations[i]}"></progress><small>Relación ${f.relations[i]} / 100 · ${f.alliances[i]?'ALIANZA ACTIVA':'Requiere embajada y 75 de relación'}</small><div class="modal-actions">${f.alliances[i]?'<b>✓ Aliado</b>':button('diplomacy','Enviar ayuda · ◈ 250',`data-id="${i}" data-type="aid"`)+button('diplomacy','Firmar alianza',`data-id="${i}" data-type="ally" ${f.relations[i]<75?'disabled':''}`)}</div></article>`).join('')}</div></section>`;
}
export function regionDetail(s,id){const r=E.regionInfo(s,Number(id));if(!r||r.status==='hidden')return '';const route=s.frontier.routes.find(v=>v.to===r.id),colony=s.frontier.colonies.find(c=>c.id===r.id);return `<article class="region-detail-card"><div><div class="eyebrow">${r.region} · ${r.naval?'RUTA MARÍTIMA':'RUTA TERRESTRE'}</div><h3>${esc(r.name)}</h3><p>${r.description}</p><p>Mineral: ${E.BIOMES[r.biome].mineral} · Riesgo: ${E.BIOMES[r.biome].disaster} · Fuerza enemiga ${r.difficulty} · Semilla ${r.seed}</p><p>${r.naval?'Necesitas cañonera y transporte. Embarca tropas junto a la costa, cruza el canal y desembarca en tierra.':'Explora con un jeep o caballería y dirige el ejército hacia los objetivos descubiertos.'}</p></div><div class="region-actions">${route?button('toggle-route',route.active?'Suspender ruta':'Reactivar ruta',`data-id="${r.id}"`):r.status!=='allied'?`<label>Origen del convoy<select id="route-origin"><option value="-1">Aurora · base inicial</option>${s.frontier.colonies.map(c=>`<option value="${c.id}">${esc(s.frontier.regions[c.id].name)}</option>`).join('')}</select></label>`+button('open-route','Establecer ruta · ◈ 200',`data-id="${r.id}"`):''}${r.status==='open'?button('expedition','EXPLORAR Y CONQUISTAR',`data-id="${r.id}" ${!route?.active?'disabled':''}`):r.status==='owned'&&!colony?`<p>Funda una civilización · ◈ 600</p>${['industry','civil','fortress'].map(t=>button('colonize',{industry:'Colonia minera',civil:'Ciudad comercial',fortress:'Fortaleza'}[t],`data-id="${r.id}" data-type="${t}"`)).join('')}`:colony?`<p>COLONIA NIV. ${colony.level} · ${colony.population} habitantes</p><p>Edificios: ${colony.buildings.map(t=>E.BUILDINGS[t].name).join(', ')}</p><p>${route?.active?'Convoyes enviando recursos a Aurora':'Exportación suspendida'} · ${Math.floor(route?.delivered||0)} segundos de servicio</p>${button('colony-city','GESTIONAR CIUDAD Y CONSTRUIR',`data-id="${r.id}"`)}${button('upgrade-colony','Ampliar civilización · ◈ '+500*colony.level,`data-id="${r.id}" ${colony.level>=5?'disabled':''}`)}`:'<p>Territorio protegido por tu alianza.</p>'}</div></article>`;}
export function researchPanel(s){return `<div class="research-panel"><h3>Laboratorio de Aurora</h3><p>Construye y mejora un laboratorio para desarrollar tecnologías permanentes.</p><div class="faction-grid">${[['weapons','Armas','+10% de daño por nivel'],['armor','Blindaje','+15% de vida de tropas nuevas por nivel'],['logistics','Logística','Más visión y menor coste de abastecimiento']].map(([t,n,d])=>`<article class="faction-card"><h3>${n} · ${s.tech[t]} / 3</h3><p>${d}</p>${button('research','Investigar · ◈ '+400*(s.tech[t]+1),`data-type="${t}" ${s.tech[t]>=3?'disabled':''}`)}</article>`).join('')}</div></div>`;}

export function colonyCity(s,id){const c=s.frontier.colonies.find(c=>c.id===id);if(!c)return '';return '<div class="colony-city"><h3>'+esc(s.frontier.regions[id].name)+' · Tu civilización</h3><canvas id="colony-preview" data-colony="'+id+'" aria-label="Vista de los edificios construidos en la colonia"></canvas><p>'+c.population+' habitantes · '+c.buildings.length+' / 20 solares · Nivel '+c.level+'</p><p>Las minas, reactores y refinerías aumentan las exportaciones. Torres, hospitales y cuarteles protegen los convoyes y reducen su exposición. Depósitos y mercados mejoran la capacidad comercial.</p><div class="colony-build-grid">'+['mine','reactor','refinery','market','turret','depot','barracks','hospital'].map(type=>'<button class="secondary" data-action="build-colony" data-id="'+id+'" data-type="'+type+'">'+E.BUILDINGS[type].name+' · ◈ '+E.BUILDINGS[type].cost.credits+'</button>').join('')+'</div></div>';}
export function drawColonyCity(s){const canvas=document.querySelector('#colony-preview');if(!canvas)return;const id=Number(canvas.dataset.colony),c=s.frontier.colonies.find(c=>c.id===id);if(!c)return;const region=s.frontier.regions[id],terrain=E.generateRegion(region.seed,region.biome,48).terrain;for(const b of E.colonyLayout(c))for(let y=b.y;y<b.y+E.BUILDINGS[b.type].size;y++)for(let x=b.x;x<b.x+E.BUILDINGS[b.type].size;x++)terrain[y*48+x]={kind:'grass',h:0};const renderer=new Renderer(canvas);renderer.camera.zoom=.9;renderer.centerOn(29,15);renderer.draw({terrain,buildings:E.colonyLayout(c),army:{},garrison:[],offers:[],battle:null,raid:null});}
